import React, { useState } from 'react';
import { Link, useLocation } from 'react-router-dom';
import { useOffline } from '../../contexts/OfflineContext';
import { useDonors } from '../../contexts/DonorContext';

const Navbar = () => {
    const [isOpen, setIsOpen] = useState(false);
    const { isOffline } = useOffline();
    const { agentAssignments } = useDonors();
    const location = useLocation();

    const isActive = (path) => location.pathname === path;

    return (
        <nav className="bg-green-700 text-white shadow-lg">
            <div className="container mx-auto px-4">
                <div className="flex justify-between items-center h-16">
                    <div className="flex-shrink-0 flex items-center">
                        <Link to="/" className="font-bold text-xl">Al-Insan Foundation</Link>
                        {isOffline && (
                            <span className="ml-3 px-2 py-1 text-xs font-semibold bg-red-600 rounded-full">
                                Offline
                            </span>
                        )}
                    </div>

                    {/* Desktop menu */}
                    <div className="hidden md:block">
                        <div className="ml-10 flex items-center space-x-4">
                            <Link
                                to="/"
                                className={`px-3 py-2 rounded-md text-sm font-medium ${isActive('/') ? 'bg-green-800' : 'hover:bg-green-600'}`}
                            >
                                Dashboard
                            </Link>
                            <Link
                                to="/register"
                                className={`px-3 py-2 rounded-md text-sm font-medium ${isActive('/register') ? 'bg-green-800' : 'hover:bg-green-600'}`}
                            >
                                Register Donor
                            </Link>
                            <Link
                                to="/donors"
                                className={`px-3 py-2 rounded-md text-sm font-medium ${isActive('/donors') ? 'bg-green-800' : 'hover:bg-green-600'}`}
                            >
                                Donor List
                            </Link>

                            {/* Dynamic Agent Tabs */}
                            {agentAssignments && agentAssignments.map((agent) => (
                                <Link
                                    key={agent.id}
                                    to={`/agent/${agent.id}`}
                                    className={`px-3 py-2 rounded-md text-sm font-medium ${isActive(`/agent/${agent.id}`) ? 'bg-green-800' : 'hover:bg-green-600'}`}
                                >
                                    {agent.name}
                                </Link>
                            ))}
                        </div>
                    </div>

                    {/* Mobile menu button */}
                    <div className="md:hidden flex items-center">
                        <button
                            onClick={() => setIsOpen(!isOpen)}
                            className="inline-flex items-center justify-center p-2 rounded-md text-white hover:bg-green-600 focus:outline-none"
                        >
                            <svg
                                className="h-6 w-6"
                                xmlns="http://www.w3.org/2000/svg"
                                fill="none"
                                viewBox="0 0 24 24"
                                stroke="currentColor"
                            >
                                {isOpen ? (
                                    <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M6 18L18 6M6 6l12 12" />
                                ) : (
                                    <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M4 6h16M4 12h16M4 18h16" />
                                )}
                            </svg>
                        </button>
                    </div>
                </div>
            </div>

            {/* Mobile menu */}
            {isOpen && (
                <div className="md:hidden">
                    <div className="px-2 pt-2 pb-3 space-y-1 sm:px-3">
                        <Link
                            to="/"
                            className={`block px-3 py-2 rounded-md text-base font-medium ${isActive('/') ? 'bg-green-800' : 'hover:bg-green-600'}`}
                            onClick={() => setIsOpen(false)}
                        >
                            Dashboard
                        </Link>
                        <Link
                            to="/register"
                            className={`block px-3 py-2 rounded-md text-base font-medium ${isActive('/register') ? 'bg-green-800' : 'hover:bg-green-600'}`}
                            onClick={() => setIsOpen(false)}
                        >
                            Register Donor
                        </Link>
                        <Link
                            to="/donors"
                            className={`block px-3 py-2 rounded-md text-base font-medium ${isActive('/donors') ? 'bg-green-800' : 'hover:bg-green-600'}`}
                            onClick={() => setIsOpen(false)}
                        >
                            Donor List
                        </Link>

                        {/* Dynamic Agent Tabs */}
                        {agentAssignments && agentAssignments.map((agent) => (
                            <Link
                                key={agent.id}
                                to={`/agent/${agent.id}`}
                                className={`block px-3 py-2 rounded-md text-base font-medium ${isActive(`/agent/${agent.id}`) ? 'bg-green-800' : 'hover:bg-green-600'}`}
                                onClick={() => setIsOpen(false)}
                            >
                                {agent.name}
                            </Link>
                        ))}
                    </div>
                </div>
            )}
        </nav>
    );
};

export default Navbar;
